html:
{% set pctx = doc._print_context or get_print_context(doc) %}
<style>
@page { size: A4; margin: 0; }
* { box-sizing: border-box; font-family: Arial, sans-serif; }
body { margin: 0; background: #fff; }
.content-area { padding: 10px 20px 140px 20px; }
.p { color: #6b2d5c; font-weight: bold; }
table { width: 100%; border-collapse: collapse; }
.head td { vertical-align: top; }
.head img { max-height: 110px; }
.doc-title { font-size: 32px; font-weight: bold; color: #6b2d5c; text-align: center; margin: 10px 0 25px; }
.info-title { font-size: 16px; font-weight: bold; color: #6b2d5c; margin-bottom: 8px; }
.items { border: 1.5px solid #000; margin-top: 10px; table-layout: fixed; }
.items th, .items td { border: 1px solid #000; padding: 6px 8px; font-size: 12px; word-wrap: break-word; }
.items th { text-align: left; }
.totals td { padding: 4px 8px; font-weight: bold; font-size: 12px; }
.stamp { width: 220px; margin: 8px 0 10px; }
.terms { margin-top: 15px; color: #6b2d5c; font-size: 13px; page-break-inside: avoid; }
.footer { position: fixed; bottom: 0; left: 0; width: 100%; height: 117px; background: #b28fb8; color: #fff; text-align: center; padding: 20px; border-top-left-radius: 16px; border-top-right-radius: 16px; font-size: 14px; line-height: 1.5; }
</style>
{% set co = frappe.get_cached_doc("Company", doc.company) %}
<div class="content-area">
<table class="head"><tr>
  <td style="width:45%"><img src="{{ co.company_logo or '/files/Alter .png' }}" alt="{{ co.name }}"></td>
  <td style="width:55%; text-align:right; vertical-align:bottom">
    <div><span class="p">Ref.No:</span> <u>{{ doc.name }}</u></div>
    <div><span class="p">Date:</span> <u>{{ doc.get_formatted("transaction_date") }}</u></div>
    <div><span class="p">Delivery Date:</span> <u>{{ doc.get_formatted("delivery_date") or '' }}</u></div>
    {% if co.tax_id %}<div><span class="p">TIN:</span> {{ co.tax_id }}</div>{% endif %}
  </td>
</tr></table>
<div class="doc-title">Sales Order</div>
<table><tr>
  <td style="width:55%; vertical-align:top">
    <div class="info-title">Client Information</div>
    <div><span class="p">Company Name:</span> <u>{{ doc.customer_name or '' }}</u></div>
    {% if doc.tax_id %}<div><span class="p">TIN:</span> <u>{{ doc.tax_id }}</u></div>{% endif %}
    <div><span class="p">Contact Person:</span> <u>{{ doc.contact_display or '' }}</u></div>
    <div><span class="p">Phone Number:</span> <u>{{ doc.contact_mobile or doc.contact_phone or '' }}</u></div>
  </td>
  <td style="width:45%; vertical-align:top; text-align:right">
    <div class="info-title">Event Details</div>
    <div><span class="p">Event Name:</span> <u>{{ doc.title or '' }}</u></div>
    {% if doc.get("event_date") %}<div><span class="p">Event Date:</span> <u>{{ doc.get_formatted("event_date") }}</u></div>{% endif %}
    {% if doc.get("event_location") %}<div><span class="p">Location:</span> <u>{{ doc.event_location }}</u></div>{% endif %}
  </td>
</tr></table>
<table class="items"><thead><tr>
  <th style="width:5%; text-align:center">No</th><th style="width:22%">Item Name</th><th style="width:30%">Description</th>
  <th style="width:10%">UOM</th><th style="width:8%; text-align:center">Qty</th>
  <th style="width:12%; text-align:right">Unit Price</th><th style="width:13%; text-align:right">Total Price</th>
</tr></thead><tbody>
{% for row in doc.items %}<tr>
  <td style="text-align:center">{{ loop.index }}</td><td>{{ row.item_name }}</td><td>{{ row.description or '' }}</td>
  <td>{{ row.uom or '' }}</td><td style="text-align:center">{{ row.get_formatted("qty") }}</td>
  <td style="text-align:right">{{ row.get_formatted("rate", doc) }}</td><td style="text-align:right">{{ row.get_formatted("amount", doc) }}</td>
</tr>{% endfor %}
</tbody></table>
<table style="margin-top:8px"><tr>
  <td style="width:60%; vertical-align:top"><img class="stamp" src="/files/Helina.png" alt="Company Stamp"></td>
  <td style="width:40%; vertical-align:top"><table class="totals">
    <tr><td>Sub Total</td><td style="text-align:right">{{ doc.get_formatted("net_total") }}</td></tr>
    {% for t in doc.taxes %}<tr><td>{{ t.description }}</td><td style="text-align:right">{{ t.get_formatted("tax_amount", doc) }}</td></tr>{% endfor %}
    {% if doc.discount_amount %}<tr><td>Discount</td><td style="text-align:right">-{{ doc.get_formatted("discount_amount") }}</td></tr>{% endif %}
    <tr><td>Grand Total</td><td style="text-align:right">{{ doc.get_formatted("rounded_total" if doc.rounded_total else "grand_total") }}</td></tr>
    {% if doc.advance_paid %}<tr><td>Advance Paid</td><td style="text-align:right">{{ doc.get_formatted("advance_paid") }}</td></tr>{% endif %}
  </table></td>
</tr></table>
{% if pctx.show_terms and doc.terms %}<div class="terms">{{ doc.terms }}</div>{% endif %}
</div>
{% set addr = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") %}
{% set a = frappe.get_cached_doc("Address", addr) if addr else None %}
<div class="footer">
  <p style="font-size:20px; font-weight:bold; margin:0 0 6px">Thank you for your business.</p>
  {% if a %}{{ a.address_line1 }}{% if a.address_line2 %}, {{ a.address_line2 }}{% endif %}, {{ a.city }}, {{ a.country }}<br>{% endif %}
  Phone: {{ co.phone_no or '' }}, Email: {{ co.email or '' }}
</div>
